/* ---------- the quest engine ----------
   Every stat owns one yearly plan. planQuests(ctx) returns one quest per plan for the day in ctx.
   ctx = {n: program day (1 = start date), wk: program week, easy: every 4th week is easier,
          wd: "Mon".."Sun", mi: planning month 0-11 (blocks of 31,28,31,30,31,30,31,31,30,31,30,31 days),
          dIn: day inside that month (1-based), lastIn: last day of that month, wkIn: week inside that month (1-4),
          dom: calendar day of month, firstTue: first Tuesday of a calendar month}
   The plans: Endurance, Speed & Agility, Looks, Knowledge & Leadership, Cognitive skills (his documents);
   Growth & Health → Height & Build, Critical thinking → Judgment, Focus, Creativity, Mindfulness → Emotional Control,
   Social skills, Influence & Leadership, Money & Income → Financial, Discipline (his Google Docs);
   Practical skills (written for him). Strength is the gym itself. */
const PLAN_XP=6, PLAN_XP_BIG=10;
const WD=["Sun","Mon","Tue","Wed","Thu","Fri","Sat"];
const q=(stat,label,detail,xp)=>({id:"pl_"+stat,stat:stat,label:label,detail:detail||"",xp:xp||PLAN_XP,plan:1});
const first7=(ctx,list)=>ctx.n>=1&&ctx.n<=list.length?list[ctx.n-1]:null;

/* Endurance — one extra 5–15 min task beside the existing gym routine. Weeks 1–2 prepare, week 3 opens Tuesday intervals,
   every 4th week is easier, Friday hard efforts unlock from week 5, the standard template from week 7. */
function pEndurance(c){
  const S="endurance";
  if(c.firstTue&&c.n>7)return q(S,"Treadmill benchmark (replaces cardio + intervals)","5 min easy · 10 min at a fixed, manageable speed and incline WITHOUT holding the rails · 5 min easy. Same treadmill, shoes and timing each month. Log speed, incline, effort /10, could-you-talk, optional HR. One reading proves nothing; the trend over 8–12 weeks does.",PLAN_XP_BIG);
  switch(c.wd){
    case "Mon":return q(S,"Prep three training snacks (10–15 min)","Carb + protein: yogurt with oats and fruit · chicken or tofu sandwich · milk with a banana and toast. Store them; eat them over the next days around training.");
    case "Tue":{
      if(c.wk<=2||c.easy)return q(S,"Bike: 6 min easy cycling after 15 min easy cardio","Preparation"+(c.easy&&c.wk>2?" (easier week)":" (weeks 1–2)")+": no hard intervals yet. Also start lowering treadmill speed/incline until you can walk without holding the rails.");
      if(c.wk<=4)return q(S,"Bike intervals: 3 × (1 min hard / 1 min easy)","After 15 min easy cardio (last 5 on the bike). Hard = 7/10, short phrases possible. Then 5 min easy + abs. Log rounds, resistance, effort. Reduce if Wednesday legs suffer.");
      if(c.wk<=6)return q(S,"Bike intervals: 3 rounds, 4 only if the last ones felt manageable","3–4 × (1 min hard / 1 min easy) after 15 min easy cardio. Hard = 7/10, repeatable. Change one variable a week at most. Log it.");
      return q(S,"Bike intervals: 4 × (1 min hard / 1 min easy)","Standard block, 8 min, after 15 min easy cardio. Later options (not yet, not both): 6 × 1 min, or 3 × (2 hard / 2 easy). Hard = 7/10. Log rounds, resistance, effort.");
    }
    case "Wed":return q(S,"10 min relaxation before bed","Sit or lie down, guided body scan or quiet breathing, natural breath, let the tension go. Ten minutes done is the completion — feeling calm is optional.");
    case "Thu":{
      const rounds=(c.wk<=4||c.easy)?"1 light round":c.wk<=6?"up to 2 light rounds":"2 rounds";
      return q(S,"Muscular endurance circuit: "+rounds+" after lifting","Incline push-ups 12–20 reps + light cable/supported row 15–20 reps, 45–60 s rest, leave 3–4 reps in the tank. Smooth reps, controlled return. Skip the row if back is cooked. Log version, load, reps, reps left.");
    }
    case "Fri":{
      if(c.wk<=4||c.easy)return q(S,"Bike: 6 min easy cycling after 15 min easy cardio","Friday stays easy until week 5"+(c.easy&&c.wk>4?" — easier week":"")+". Saturday is legs, so this is always the first thing to drop when tired.");
      return q(S,"Short hard bike efforts: 3 × (15 s hard / 1:45 very easy)","Only if Tuesday and leg day recovered well. After 15 min easy cardio. Hard = 8/10, seated, smooth, not all-out; stop when output falls. 4 rounds is a later option. Log reps, settings, effort, and how legs feel Saturday.");
    }
    case "Sat":return q(S,"Prep Sunday's food and bottle (10 min)","One carb meal or snack ready (oats + yogurt, sandwich + fruit, rice + eggs/chicken), bottle filled, decide where water will be. Electrolytes only if hot or sweaty.");
    default:return q(S,"Weekly endurance scorecard (5–8 min after cardio)",(c.easy?"Easier week: today's cardio can be ~25% shorter. ":"")+"Record: extra tasks done or modified · Sunday duration, distance, effort /10 · Tuesday/Friday repeatability · Thursday reps and load · sleep, soreness, energy, leg-day performance. One decision for next week: maintain, progress ONE variable, or reduce.",PLAN_XP_BIG);
  }
}

