const SPEED_M=["Baseline and landing","Skipping and acceleration","Vertical power","Lateral control","Braking and turning","Midyear review: two measures improved?","Your weakest measured quality","Elastic rhythm: brief low hops","Responding and choosing","Sport application: first step and rotational landings","Maintenance with sport","Final review: full baseline scorecard"];
function pSpeed(c){
  const S="speed",focus="Month "+(c.mi+1)+": "+SPEED_M[c.mi]+".";
  if(c.n===1)return q(S,"Skipping and landing introduction (10 min)","0–3 brisk walk → easy marching, ankle circles · 3–6 three rounds of 15 s gentle skipping + 45 s walking · 6–9 six small vertical jumps, one every 30 s, hold each landing 2 s · 9–10 record leg freshness and whether landings felt controlled. Quiet landings, easy rhythm.");
  const tests=["Test: 10 m acceleration on film","Test: vertical jump + standing broad jump","Test: 3 m lateral shuffle + phone reaction (median of 10)"];
  const testDetail=["Fixed side camera showing start and finish, slow-motion. Time first movement → torso crossing the line. 3 attempts with full rest; record best and median. Same warm-up, shoes, surface every time.","Vertical: standing reach vs jump reach, same arm. Broad: from a fixed line to the nearer heel, hold the landing; a failed landing is recorded separately. 3 attempts each, best and median.","Shuffle 3 m out and back without crossing feet, same touch rule, each starting side timed separately. Then the same stationary phone test: 5 practice, record the median of 10 valid tries and the error count."];
  const ti=(c.n>=2&&c.n<=4)?c.n-2:(c.n>=16&&c.n<=18)?c.n-16:(c.mi>0&&c.dIn>=1&&c.dIn<=3)?c.dIn-1:-1;
  if(ti>=0)return q(S,tests[ti],(c.n<=18?"Baseline"+(c.n>=16?" repeat — you need the normal spread before targets mean anything. ":". "):"Monthly test replaces training. ")+testDetail[ti]+" "+focus,PLAN_XP_BIG);
  const half=c.easy?" (easier week: about half the reps)":"";
  switch(c.wd){
    case "Mon":return q(S,"Easy coordination (10 min, low effort)","Pick one: gentle skipping with walking breaks · single-leg balance · easy wall catches · a stationary phone reaction task. "+focus);
    case "Tue":return q(S,"Recovery: comfortable hip and ankle mobility","Easy, 5–10 min, nothing forced. Full rest is also a valid answer today. "+focus);
    case "Wed":{
      if(c.wk%2===1)return q(S,"Before legs: jumps and landings"+half,"5 min warm-up. 2 × 3 small vertical jumps, reset between reps, 60–90 s between sets, hold each landing 2 s, knees tracking over feet. Later: forward, lateral, skater, small rotational — 6–12 deliberate jumps total. Land quietly, stay balanced. "+focus);
      return q(S,"Before legs: braking and turning"+half,"5 min warm-up. 4 short reps alternating sides, 45–60 s rest: controlled approach → gradual brake → turn → re-accelerate. Add the reversal and diagonal patterns once turns stay clean. Slow down before the turn, then push away. "+focus);
    }
    case "Thu":return q(S,"Easy solo reaction or goalkeeper anticipation","Pause match footage just before the shot, call the direction, check. Or an easy reaction drill. Low effort. "+focus);
    case "Fri":return q(S,"Recovery and movement technique","Easy marching, relaxed skipping, two gradual build-ups — technique, not speed. Skip it entirely if a ski trip or soccer already loaded the legs. "+focus);
    case "Sat":{
      if(c.wk<=4||c.easy)return q(S,"Before legs: acceleration 3 × 5 m at 70–80%"+half,"5 min progressive warm-up (walk, march, gentle skips, two build-ups). 3 × 5 m, 60 s rest. Push the ground away and let speed build; don't reach with the foot. Soccer counts instead if you played hard. "+focus);
      return q(S,"Before legs: acceleration 3 × 10 m, 90 s rest","5 min progressive warm-up. 3 × 10 m relaxed-fast, full rests. Occasional longer relaxed accelerations only if fresh, with space and time. Reduce reps rather than rush rest. "+focus);
    }
    default:return q(S,"Recovery + weekly speed check-in","Leg freshness 1–5, any pain and where, gym/endurance done, soccer or skiing coming up. Progress only after two clean, pain-free exposures; change one feature at a time. "+focus);
  }
}

