  if(!row)return q(S,t,"The calendar's focused task for day "+(i+1)+". Keep the basic routine (morning cleanse/moisturize/SPF, evening cleanse/moisturize) running alongside."+tag);
  if(t==="C")return q(S,row[0],row[1]+tag,PLAN_XP_BIG);
